/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import MarkdownIt from 'markdown-it';
const md = new MarkdownIt({html: false, linkify: true, breaks: false});
const html = md.render('# Заголовок\\n\\n**Важно** и *курсив*\\n\\n- Пункт\\n\\n> Цитата\\n\\n[ссылка](https://example.com)\\n\\n"'`код`'"');
for (const expected of ['<h1>Заголовок</h1>', '<strong>Важно</strong>', '<em>курсив</em>', '<ul>', '<blockquote>', 'href=\"https://example.com\"', '<code>код</code>']) assert.ok(html.includes(expected), expected);
assert.equal(md.render(''), '');
assert.ok("'!md.render('"'<script>alert(1)</script>').includes('<script>'));
assert.ok("'!md.render('"'[test](javascript:alert(1))').includes('href=\"javascript:'));
assert.ok(md.render('[ссылка](https://пример.рф)').includes('xn--'));
console.log('Markdown checks passed: formatting, empty text, HTML escaping, unsafe URLs, international URLs.');
JS

git diff --check"
